  const lookup=(list,id)=>list?.find(x=>x.id===id)?.name||'—',tabs='<nav class="s46-tabs" aria-label="'+esc(this.t('基础资料类型','Master data types'))+'">'+Object.entries(types).map(([key,[z,e]])=>'<a href="/customers/master-data?type='+key+'" '+(key===type?'aria-current="page"':'')+'>'+this.L(z,e)+'</a>').join('')+'</nav>',filters='<form id="s46-master-filter" class="s46-filter"><input name="type" type="hidden" value="'+type+'"><div class="s46-master-filters"><label>'+this.L('编码 / 名称','Code / Name')+'<input name="search" maxlength="120" value="'+esc(search)+'" placeholder="'+esc(this.t('输入关键词','Enter a keyword'))+'"></label><label>'+this.L('状态','Status')+'<select name="status">'+[['active','启用','Active'],['disabled','停用','Inactive'],['','全部','All']].map(([v,z,e])=>'<option value="'+v+'" '+(status===v?'selected':'')+'>'+esc(this.t(z,e))+'</option>').join('')+'</select></label><div class="s46-actions">'+this.link('/customers/master-data?type='+type,'重置','Reset')+'<button class="button primary">'+this.L('查询','Search')+'</button></div></div></form>';
  const cols=[['编码','Code'],[type==='batches'?'生产日期':'名称',type==='batches'?'Production Date':'Name'],['所属项目','Project'],...(type==='warehouses'?[['启用堆场数','Active Yards'],['启用货位数','Active Locations']]:type==='yards'?[['所属仓库','Warehouse'],['启用货位数','Active Locations']]:type==='locations'?[['所属仓库','Warehouse'],['所属堆场','Yard']]:[]),['状态','Status'],['操作','Actions']];
